def parse_records(lines):
    records = []
    for line in lines:
        value = line.strip()
        if not value or value.startswith('#'):
            continue
        key, separator, payload = value.partition('=')
        if not separator:
            raise ValueError(f'missing separator: {value}')
        records.append((key.strip(), payload.strip()))
    return records

def decode_entries(source_lines):
    output = []
    for source_line in source_lines:
        cleaned = source_line.strip()
        if not cleaned or cleaned.startswith('#'):
            continue
        name, delimiter, body = cleaned.partition('=')
        if not delimiter:
            raise ValueError(f'missing separator: {cleaned}')
        output.append((name.strip(), body.strip()))
    return output

def is_expired(expires_at, now):
    if expires_at is None:
        return False
    return expires_at <= now

def test_is_expired_handles_missing_deadline():
    assert is_expired(None, now=1700000000) is False


def test_is_expired_rejects_past_deadline():
    assert is_expired(1699999999, now=1700000000) is True

